<?php defined('_JEXEC') or die;use Joomla\CMS\HTML\HTMLHelper;use Joomla\CMS\Router\Route; ?><div class="container-fluid kaar-booking"><h1>Bookings</h1><div class="row g-3 mb-4"><?php foreach($this->stats as $k=>$v): ?><div class="col-6 col-lg-3"><div class="card"><div class="card-body"><div class="text-muted"><?php echo ucfirst($k); ?></div><strong class="fs-3"><?php echo $v; ?></strong></div></div></div><?php endforeach; ?></div><div class="card mb-4"><div class="card-body"><h2 class="h4">Take booking by phone</h2><form action="<?php echo Route::_('index.php?option=com_kaarbooking&task=booking.createPhone'); ?>" method="post" class="row g-3"><div class="col-md-3"><input class="form-control" name="customer_name" required placeholder="Customer name"></div><div class="col-md-2"><input class="form-control" name="customer_phone" required placeholder="Phone"></div><div class="col-md-3"><input class="form-control" type="email" name="customer_email" placeholder="Email"></div><div class="col-md-2"><select class="form-select" name="product_type"><option value="vehicle">Vehicle booking</option><option value="package">Tour package</option></select></div><div class="col-md-2"><input class="form-control" type="datetime-local" name="departure_at" required></div><div class="col-md-3"><select class="form-select" name="vehicle_type_id"><option value="">Vehicle type</option><?php foreach($this->types as $t): ?><option value="<?php echo $t['id']; ?>"><?php echo htmlspecialchars($t['title'],ENT_QUOTES,'UTF-8'); ?></option><?php endforeach; ?></select></div><div class="col-md-3"><select class="form-select" name="package_id"><option value="">Tour package</option><?php foreach($this->packages as $p): ?><option value="<?php echo $p['id']; ?>"><?php echo htmlspecialchars($p['title'],ENT_QUOTES,'UTF-8'); ?></option><?php endforeach; ?></select></div><div class="col-md-2"><select class="form-select" name="service_type"><option value="outstation">Outstation</option><option value="local_day">Full day</option><option value="local_half_day">Half day</option><option value="airport">Airport</option><option value="tour_package">Tour package</option><option value="wedding_event">Wedding/event</option></select></div><div class="col-md-2"><select class="form-select" name="driver_mode"><option value="with_driver">With driver</option><option value="self_drive">Without driver</option></select></div><div class="col-md-1"><input class="form-control" type="number" min="1" name="passengers" value="1" title="Passengers"></div><div class="col-md-3"><input class="form-control" name="origin_text" placeholder="Pickup/origin"></div><div class="col-md-3"><input class="form-control" name="destination_text" placeholder="Destination"></div><div class="col-md-2"><input class="form-control" type="number" min="0" step=".01" name="total_amount" placeholder="Quoted amount"></div><div class="col-md-3"><input class="form-control" name="admin_notes" placeholder="Call notes"></div><div class="col-md-2"><button class="btn btn-primary">Create booking</button></div><?php echo HTMLHelper::_('form.token'); ?></form></div></div><form method="get" class="row g-2 mb-3"><input type="hidden" name="option" value="com_kaarbooking"><input type="hidden" name="view" value="bookings"><div class="col-md-3"><input class="form-control" name="filter_search" value="<?php echo htmlspecialchars($this->filters['search'],ENT_QUOTES,'UTF-8'); ?>" placeholder="Reference, customer or phone"></div><div class="col-md-2"><select class="form-select" name="filter_status"><option value="">All statuses</option><option>pending_admin_review</option><option>confirmed</option><option>allocated</option><option>completed</option><option>cancelled</option></select></div><div class="col-md-2"><select class="form-select" name="filter_source"><option value="">All sources</option><option>phone</option><option>website</option><option>flutter_customer</option><option>realtime_dispatch</option></select></div><div class="col-md-2"><input class="form-control" type="date" name="filter_from" value="<?php echo htmlspecialchars($this->filters['from'],ENT_QUOTES,'UTF-8'); ?>"></div><div class="col-md-2"><input class="form-control" type="date" name="filter_to" value="<?php echo htmlspecialchars($this->filters['to'],ENT_QUOTES,'UTF-8'); ?>"></div><div class="col-md-1"><button class="btn btn-secondary">Filter</button></div></form><div class="table-responsive"><table class="table table-striped"><thead><tr><th>Reference/source</th><th>Customer</th><th>Trip</th><th>Departure</th><th>Status</th><th>Payment</th><th>Manual action</th></tr></thead><tbody><?php foreach($this->items as $i): ?><tr><td><?php echo htmlspecialchars($i['reference'],ENT_QUOTES,'UTF-8'); ?><br><small><?php echo htmlspecialchars($i['source'],ENT_QUOTES,'UTF-8'); ?></small></td><td><?php echo htmlspecialchars($i['customer_name'],ENT_QUOTES,'UTF-8'); ?><br><small><?php echo htmlspecialchars($i['customer_phone'],ENT_QUOTES,'UTF-8'); ?></small></td><td><?php echo htmlspecialchars($i['service_type'],ENT_QUOTES,'UTF-8'); ?><br><small><?php echo htmlspecialchars($i['origin_text'].' → '.$i['destination_text'],ENT_QUOTES,'UTF-8'); ?></small></td><td><?php echo $i['departure_at']; ?></td><td><?php echo $i['status']; ?></td><td><?php echo $i['payment_status']; ?></td><td><form action="<?php echo Route::_('index.php?option=com_kaarbooking&task=booking.transition'); ?>" method="post" class="d-flex gap-2"><input type="hidden" name="id" value="<?php echo $i['id']; ?>"><select name="status" class="form-select form-select-sm"><option value="quoted">Quote</option><option value="pending_payment">Await payment</option><option value="confirmed">Confirm</option><option value="allocated">Allocate</option><option value="rejected">Reject</option><option value="cancelled">Cancel</option></select><input name="reason" class="form-control form-control-sm" placeholder="Reason"><button class="btn btn-primary btn-sm">Apply</button><?php echo HTMLHelper::_('form.token'); ?></form></td></tr><?php endforeach; ?><?php if(!$this->items): ?><tr><td colspan="7">No bookings match the filters.</td></tr><?php endif; ?></tbody></table></div></div>
